solution.python:
import sys

for line in sys.stdin.read().split("\n"):
    if not line.strip():
        continue
    qism = line.split(".")
    a = int(qism[0])
    b = int(qism[1])
    if a == 10 or (a == 192 and b == 168) or (a == 172 and 16 <= b <= 31):
        print("private")
    else:
        print("public")

